
#!/usr/bin/env python3
"""
August design system integration -- Phase 5: real Inter Variable font.

Continuation of phases 1-4. Run this from the repo root AFTER phases 1-4
are applied and compiling green -- it edits AugustTokens.kt, which phase 1
created and phase 2/3 already extended, and adds one new font resource.

Background: AugustTypography (phase 1) has used FontFamily.Default (the
system sans) since it was written -- bundling the doc's actual specified
typeface, Inter Variable, was deliberately deferred pending a product
decision between two real options: Android's Downloadable Fonts API (which
depends on Google Play Services' Fonts Provider) or bundling an actual font
file in the APK. Given this app's whole target audience is Huawei devices
without GMS, the Downloadable Fonts API isn't a safe default here -- it
would silently fail to resolve the font on exactly the devices this app is
built for. Bundling a real, offline-safe font file is the only option that
doesn't depend on Google Play Services, so that's what this script does.

What this script does:

1. Adds app/src/main/res/font/inter_variable.ttf -- a single variable font
   file (both weight and optical-size axes) sourced from Google's own font
   repository (github.com/google/fonts, ofl/inter/Inter[opsz,wght].ttf,
   OFL-1.1 licensed), then subsetted with fonttools' pyftsubset to Latin +
   Cyrillic (this app is EN/RU only), cutting it from 876KB to 481KB. The
   subset was verified glyph-by-glyph against every distinct character
   actually used in both values/strings.xml and values-ru/strings.xml --
   the only 2 characters not covered were emoji (🎉/🎯), which Inter never
   covers regardless of subsetting (no text typeface ships emoji glyphs;
   Android's font-fallback chain renders those from the system emoji font
   automatically no matter what font this app requests, so this isn't a
   real gap). The exact bytes below are the same file this was tested
   against -- not re-fetched or re-subsetted at patch time -- so what you
   get is exactly what was verified, with no dependency on network access
   or fonttools being installed in this environment.

2. Rewrites AugustTokens.kt's AugustFont.Family to reference that font,
   registered at every distinct FontWeight value used ANYWHERE in the app
   -- not just AugustTypography's own 9 styles -- verified by grepping
   every FontWeight.* and TextStyle fontWeight literal across
   FinalBitLutShell.kt, GlassCards.kt, GlassNavigation.kt and
   ImportScreen.kt: 450/500/600/650/700/750/780/800/820/850/900.

   This has app-wide effect without touching any of those ~100+ individual
   Text() calls: none of them set their own `fontFamily` (the app's one
   exception, a monospace id/hash display, already opts out explicitly
   with FontFamily.Monospace), so Compose's Text() merges the unspecified
   fontFamily from the ambient LocalTextStyle -- which MaterialTheme sets
   from AugustTypography -- meaning every Text() call in the app inherits
   whatever AugustFont.Family resolves to. Verified by grepping for
   ProvideTextStyle/LocalTextStyle overrides anywhere in the app's own
   code (there are none) that could break that inheritance chain.

   The optical-size axis (opsz, the font's other variable axis, 14-32) is
   intentionally left unset on every entry: this app's real weight range
   sits at or near the font's own default opsz of 14, so an explicit value
   would be redundant with the default rather than a deliberate choice --
   and a single FontWeight can't carry two different opsz values through
   Compose's family-matching (e.g. weight 850 is used by both displayLarge,
   which would want a larger opsz, and labelSmall, which would want a
   smaller one), so a uniform value was the only option that didn't need
   per-TextStyle fontFamily overrides.

Font resource note: this is the one step that isn't pure text patching, so
it isn't run through the same apply_edit/apply_insertion helpers as the
rest of this integration -- it's an idempotent whole-file write, verified
by SHA-256 rather than by diffing (diffing binary content doesn't mean
anything). If app/src/main/res/font/inter_variable.ttf already exists with
this exact content, this step is a no-op; if it exists with *different*
content, this script stops rather than overwriting an unknown file.

Run from the repo root:
    python3 august_phase5_inter_font.py
"""
import base64
import datetime
import hashlib
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent
BACKUP_DIR = ROOT / ".bitlut_patch_backup" / datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

THEME_DIR = "app/src/main/java/com/openhealth/sync/ui/theme"
AUGUST_TOKENS = f"{THEME_DIR}/AugustTokens.kt"
FONT_RESOURCE = "app/src/main/res/font/inter_variable.ttf"

TARGET_FILES = [AUGUST_TOKENS]
# FONT_RESOURCE is a new binary file, handled separately from the text
# TARGET_FILES (backed up conditionally, verified by hash not by diff).

EXPECTED_FONT_SHA256 = "0d3384548fb5a343929348b2746a8901b0abcbac987f47a05507c1ea6660e020"

